import './neon-progress-indicator.scss';
import { NeonWidget } from '../shared/neon-widget';
import { dynamicText, createElement, updateDynamicText, updateDynamicAttribute, dynamicAttr, updateConditionalElements, dynamicClass } from '../shared/dom-manipulation';
import { addTranslationListener, translate, formatNumber } from '@ps-refarch-ux/mfe-utils';
import { tooltipOnEllipsis, TooltipOnEllipsisObserver } from '../shared/extensions/tooltip-on-ellipsis';
// data-label-text: string
// data-layout: string 'simple' | 'wide' | 'condensed' | 'bar-only';
// data-color: 'magenta' | 'orange' | 'green' | 'teal' | 'cyan' | 'navy' | 'purple'
// data-bar-height: 'small' | 'medium' | 'large'
// data-is-percent: boolean
// value: number
// data-total: number
// data-max-decimal: number
// data-show-label is not needed.  The label shows in the wide and condensed layout
// data-show-label: boolean
export class NeonProgressIndicator extends NeonWidget {
    constructor() {
        super();
        this.widgetTag = 'neon-progress-indicator';
        this.isIdRequired = true;
        this.tooltipOnEllipsisObserver = new TooltipOnEllipsisObserver(this);
    }
    //Any attribute that should be watched for changes should be listed here.
    static get observedAttributes() {
        return [
            'id',
            'data-label-text',
            'data-layout',
            'data-color',
            'data-bar-height',
            'data-show-label',
            'data-is-percent',
            'value',
            'data-total',
            'data-max-decimals'
        ];
    }
    //when the attributes change this will run
    attributeChanged(attrName, oldVal, newVal) {
        super.attributeChanged(attrName, oldVal, newVal);
        // attributeChanged is called when attributes listed in "static get observedAttributes()" are changed.
        switch (attrName) {
            case 'id':
                updateDynamicAttribute(this, 'id');
                break;
            case 'data-layout':
                updateConditionalElements(this);
                updateDynamicAttribute(this, 'class');
                break;
            case 'value':
                updateDynamicAttribute(this, 'value');
                updateDynamicText(this);
                break;
            case 'data-total':
                updateDynamicAttribute(this, 'max');
                updateDynamicText(this);
                break;
            case 'data-is-percent':
                updateDynamicText(this);
                break;
            case 'data-label-text':
                updateDynamicText(this);
                break;
            case 'data-max-decimals':
                updateDynamicText(this);
                break;
            default:
        }
    }
    validateInputs() {
        if (this.getAttribute('data-label-text') == null || this.getAttribute('data-label-text') === '') {
            console.error('data-label-text is required for accessibility and screen reader purposed on', this);
        }
    }
    render() {
        return createElement('label', {
            attrs: {
                class: dynamicAttr(() => {
                    return this.getAttribute('data-layout');
                })
            }
        }, createElement('span', {
            attrs: {
                class: dynamicClass({
                    'neon-progress-indicator-label-text': true,
                    'neon-sr-only': (this.getLayout() !== 'wide' && this.getLayout() !== 'condensed'),
                })
            },
            text: dynamicText(() => {
                return this.getAttribute('data-label-text');
            }),
            extensions: tooltipOnEllipsis
        }), createElement('span', {
            attrs: {
                class: dynamicAttr(() => { return 'neon-progress-indicator-progress-text' + (this.getLayout() === 'bar-only' ? ' neon-sr-only' : ''); })
            },
            text: dynamicText(() => {
                if (this.getAttribute('data-is-percent') === 'true') {
                    return this.getPercent() + '%';
                }
                else {
                    return translate('neon|progress-indicator|xx of xx', { value: formatNumber(this.getValue(), this.getMaxDecimals(undefined)), total: formatNumber(this.getTotal(), this.getMaxDecimals(undefined)) });
                }
            })
        }), createElement('progress', {
            attrs: {
                class: dynamicAttr(() => {
                    return this.getAttribute('data-bar-height');
                }),
                min: '0',
                max: dynamicAttr(() => {
                    return this.getAttribute('data-total');
                }),
                value: dynamicAttr(() => {
                    return this.getAttribute('value');
                })
            }
        }));
    }
    getLayout() {
        const layout = this.getAttribute('data-layout');
        switch (layout) {
            case 'simple':
            case 'wide':
            case 'condensed':
            case 'bar-only':
                return layout;
            default:
                return 'simple';
        }
    }
    connectedCallback() {
        //The observer needs to be turned on when render() gets called.
        //That's why it's above super.connectedCallback()
        this.tooltipOnEllipsisObserver.connect();
        super.connectedCallback();
        this.i18nUnsubscribe = addTranslationListener(() => {
            updateDynamicText(this);
        });
    }
    disconnectedCallback() {
        if (this.i18nUnsubscribe != null) {
            this.i18nUnsubscribe();
            this.i18nUnsubscribe = undefined;
        }
        this.tooltipOnEllipsisObserver.disconnect();
    }
    getValue() {
        const valueAttr = this.getAttribute('value');
        if (valueAttr == null) {
            return 0;
        }
        const value = Number(valueAttr);
        if (isNaN(value)) {
            return 0;
        }
        return value;
    }
    getTotal() {
        const totalAttr = this.getAttribute('data-total');
        if (totalAttr == null) {
            return 0;
        }
        const total = Number(totalAttr);
        if (isNaN(total)) {
            return 0;
        }
        return total;
    }
    getPercent() {
        const total = this.getTotal();
        //Gotta do the divide by zero check.
        if (total === 0) {
            return '0';
        }
        return formatNumber(this.getValue() / total * 100, this.getMaxDecimals(0)) || '0';
    }
    //When we show the percent, we will pass in 0 as the defaultValue.
    //When we show the number, we will pass in undefined as the defaultValue
    getMaxDecimals(defaultValue) {
        const maxDecimalsAttr = this.getAttribute('data-max-decimals');
        if (maxDecimalsAttr == null) {
            return defaultValue;
        }
        const maxDecimals = Number(maxDecimalsAttr);
        if (isNaN(maxDecimals)) {
            return defaultValue;
        }
        return Math.floor(maxDecimals);
    }
}
